import { useState } from 'react';
import styles from './App.module.css';

export default function App() {
  const [notes, setNotes] = useState([]);
  const [draft, setDraft] = useState('');
  const addNote = (event) => {
    event.preventDefault();
    const value = draft.trim();
    if (!value) return;
    setNotes((current) => [...current, value]);
    setDraft('');
  };
  return <main className={styles.app}><section className={styles.shell}><h1 className={styles.title}>Notes</h1><form className={styles.field} onSubmit={addNote}><label className={styles.label} htmlFor="note">New note</label><input id="note" className={styles.control} value={draft} onChange={(event) => setDraft(event.target.value)} /><button className={styles.primaryAction} type="submit">Add note</button></form>{notes.length ? <ul className={styles.list}>{notes.map((note) => <li className={styles.item} key={note}>{note}</li>)}</ul> : <p className={styles.muted}>No notes yet.</p>}</section></main>;
}
